async (page) => { await page.getByRole('button', { name: 'Delete' }).click(); await page.waitForTimeout(1000);
// scroll grid to bottom and collect Avaya closed rows
const out = new Set();
for (let i=0;i<30;i++){
 const rows = await page.evaluate(()=>{const g=document.querySelector('vaadin-grid'); return [...g.querySelectorAll('tr')].map(r=>[...r.querySelectorAll('td')].map(c=>c.innerText.trim()).join('|'))});
 rows.forEach(r=>out.add(r));
 await page.evaluate(()=>{const g=document.querySelector('vaadin-grid'); g.scrollToIndex(Math.min(g._effectiveSize-1, (g._lastVisibleIndex||0)+20))});
 await page.waitForTimeout(300);
}
return [...out].filter(r=>r.includes('Avaya')); }
